pub fn queue_order(inventory: &mut Inventory, names: &[&str], customer: &str) -> String {
    for name in names {
        if !inventory.reserve(name) {
            return format!("Waiting for stock: {}", customer);
        }
    }
    reserve(names, customer)
}

